contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount1 > 0);
        require(amount2 > 0);
        require(amount1 <= address(this).balance);
        require(amount2 <= address(this).balance - amount1);
        uint cBefore = address(c).balance;
        uint tBefore = address(this).balance;
        c.sendTo(address(this), amount1); if (__ESBMC_reverted()) return;
        c.sendTo(address(this), amount2); if (__ESBMC_reverted()) return;
        assert(address(c).balance + amount1 + amount2 == cBefore &&
               address(this).balance == tBefore + amount1 + amount2);
    }
    receive() external payable {}
}

