// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(amount1 <= address(this).balance);
        vm.assume(amount2 <= address(this).balance - amount1);
        uint cBefore = address(c).balance;
        uint tBefore = address(this).balance;
        try c.sendTo(address(this), amount1) {} catch { return; }
        try c.sendTo(address(this), amount2) {} catch { return; }
        assertTrue(address(c).balance + amount1 + amount2 == cBefore &&
               address(this).balance == tBefore + amount1 + amount2);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
